/* Presentation metadata and Manager lookup editing. */
function categoryValues(c,d){const u=state.units.find(u=>u.id===c.unit),a=u?.attributes.find(a=>a.name===d.name);if(String(d.type).toLowerCase()==='boolean')return ['true','false'];const declared=a?.valuesText?.split(',').map(x=>x.trim()).filter(Boolean)||a?.values||a?.allowedValues;if(declared?.length)return [...new Set(declared.map(String))];return u?.sample?[...new Set(sampleUnits.filter(r=>r.status==='Delivered').map(r=>r[d.name]).filter(v=>v!=null).map(String))]:[]}
function conditionWords(c){const label=k=>c.display?.labels?.[k]||displayKey(k).replaceAll('_',' '),op={'=':'is','!=':'is not','>':'is greater than','>=':'is at least','<':'is less than','<=':'is at most',IN:'is one of','NOT IN':'is not one of',BETWEEN:'is between'};const parts=(c.filters||[]).map(f=>`${label(f.key)} ${op[f.op]||f.op} ${f.value}`);if(c.unitFilterKey)parts.push(`${label(c.unitFilterKey)} ${op[c.unitFilterOp]||c.unitFilterOp} ${c.unitFilterValue}`);return parts.join(c.filterJoin==='OR'?' OR ':' AND ')}
function conditionCopy(c){return c.conditionTextCustom?c.conditionText||'':conditionWords(c)}
const riderUnitForm=unitForm;
unitForm=function(){riderUnitForm();const box=document.createElement('div');box.className='panel-body';box.innerHTML=(draft.attributes||[]).map((a,i)=>!numericType(a.type)&&a.type!=='Boolean'?input('Available values · '+esc(a.name),`attributes.${i}.valuesText`,a.valuesText||(a.values||[]).join(', '),'text','Comma-separated source values used to populate Manager templates.'):'' ).join('');document.querySelector('#editor .dialog-body').append(box)};
const riderComponentForm=componentForm;
componentForm=function(c,i){c.display||={};c.display.units||={};const u=state.units.find(x=>x.id===c.unit);return riderComponentForm(c,i).replace('</section>',`<div class="panel-body">${(c.basis==='Per Unit'?lookupDimensions(c):[]).filter(d=>numericType(d.type)).map(d=>input('Unit suffix · '+esc(d.name),`components.${i}.display.units.${d.name}`,c.display.units[d.name]||u?.attributes.find(a=>a.name===d.name)?.unit||'','text','For example KG, KM or hours.')).join('')}</div></section>`)};
for(const u of state.units)if(u.id==='shipment')for(const a of u.attributes)if(a.name==='weight_kg')a.unit||='KG';
const riderRatesFor=ratesFor;
ratesFor=function(c){if(c.basis!=='Per Unit'||c.lookup==='Flat')return [];let combos=[[]];for(const d of lookupDimensions(c)){const vals=numericType(d.type)?[{min:0,max:'+'}]:categoryValues(c,d);combos=combos.flatMap(keys=>vals.map(v=>[...keys,clone(v)]))}return combos.map(keys=>({keys,value:0}))};
function lastBand(c,j,k){const r=c.rates[j];return !c.rates.some((x,i)=>i!==j&&x.keys.every((v,n)=>n===k||JSON.stringify(v)===JSON.stringify(r.keys[n]))&&Number(x.keys[k]?.min)>Number(r.keys[k]?.min))}
lookupTable=function(c,i){const dims=lookupDimensions(c),numeric=dims.some(d=>numericType(d.type));return `${!(c.rates||[]).length?'<p class="notice">No attribute values are available. Add source values in the Unit registry.</p>':''}${table([...dims.map(d=>esc(c.display?.labels?.[d.name]||d.name.replaceAll('_',' '))),esc(c.display?.valueLabel||'Value'),''],(c.rates||[]).map((r,j)=>row([...dims.map((d,k)=>numericType(d.type)?`<div class="grid"><label>Minimum<input type="number" step="${d.type==='Integer'?'1':'any'}" data-k="components.${i}.rates.${j}.keys.${k}.min" value="${esc(r.keys[k]?.min??'')}"></label><label>Maximum${lastBand(c,j,k)?' (optional)':''}<input type="text" data-range-max data-optional-max="${lastBand(c,j,k)}" placeholder="${lastBand(c,j,k)?'Optional (+)':'Maximum'}" data-k="components.${i}.rates.${j}.keys.${k}.max" value="${r.keys[k]?.max==='+'?'':esc(r.keys[k]?.max??'')}"></label></div>`:`<span>${esc(String(d.type).toLowerCase()==='boolean'?String(r.keys[k]).toUpperCase():r.keys[k])}</span>`),`<input type="number" step="any" data-k="components.${i}.rates.${j}.value" value="${esc(r.value)}" aria-label="Value">`,numeric?`<button data-lookup-remove="${i}|${j}">Remove range</button>`:'']))) }${numeric?`<button data-add-band="${i}">+ Add range</button><p class="quiet">Leave the last maximum empty for an open-ended range.</p>`:''}`};
function populateCategories(c){if(c.basis!=='Per Unit'||c.lookup==='Flat')return;const dims=lookupDimensions(c),cats=dims.filter(d=>!numericType(d.type));if(!cats.length)return;let combos=[[]];for(const d of cats)combos=combos.flatMap(row=>categoryValues(c,d).map(v=>[...row,v]));if(!combos.length)return;const patterns=new Map();for(const r of c.rates||[])patterns.set(JSON.stringify(r.keys.filter((v,i)=>numericType(dims[i].type))),r.keys.filter((v,i)=>numericType(dims[i].type)));if(!patterns.size)patterns.set('default',dims.filter(d=>numericType(d.type)).map(()=>({min:0,max:'+'})));c.rates||=[];for(const combo of combos)for(const bands of patterns.values()){let ci=0,ni=0;const keys=dims.map(d=>numericType(d.type)?clone(bands[ni++]):combo[ci++]);if(!c.rates.some(r=>JSON.stringify(r.keys)===JSON.stringify(keys)))c.rates.push({keys,value:0})}}
const riderTemplateForm=templateForm;
templateForm=function(){for(const c of draft.components||[]){populateCategories(c);if(!c.conditionTextCustom)c.conditionText=conditionWords(c);}riderTemplateForm();const body=document.querySelector('#editor .dialog-body');for(const [i,section] of [...body.querySelectorAll('section.panel')].entries()){const c=draft.components[i];if(!c)break;const box=document.createElement('div');box.className='panel-body';box.innerHTML=`<label class="section-gap">Condition text<textarea data-condition-text="${i}" data-k="components.${i}.conditionText" rows="2">${esc(conditionCopy(c))}</textarea></label>`;section.append(box)}};
document.addEventListener('input',e=>{const el=e.target;if(editorType!=='template'||!draft)return;if(el.dataset.optionalMax==='true'&&el.value.trim()==='')setPath(draft,el.dataset.k,'+');if(el.dataset.conditionText!==undefined)draft.components[Number(el.dataset.conditionText)].conditionTextCustom=true;else if(/\.(filters|unitFilter|filterJoin)/.test(el.dataset.k||'')){const i=Number(el.dataset.k.split('.')[1]),c=draft.components[i];if(c&&!c.conditionTextCustom){c.conditionText=conditionWords(c);const field=document.querySelector(`[data-condition-text="${i}"]`);if(field)field.value=c.conditionText}}});
document.addEventListener('change',e=>{if(editorType==='template'&&e.target.dataset.k?.endsWith('.filterJoin'))templateForm()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-add-band]');if(!b)return;const c=draft.components[Number(b.dataset.addBand)],dims=lookupDimensions(c),k=dims.findIndex(d=>numericType(d.type));if(k<0)return;const groups=new Map();for(const r of c.rates){const key=JSON.stringify(r.keys.map((v,n)=>n===k?null:v));if(!groups.has(key)||Number(r.keys[k].min)>Number(groups.get(key).keys[k].min))groups.set(key,r)}for(const r of groups.values()){const last=r.keys[k];const boundary=last.max==='+'?Number(last.min)+5:Number(last.max);last.max=boundary;const next=clone(r);next.keys[k]={min:boundary,max:'+'};next.value=0;c.rates.push(next)}templateForm()});
const riderValidate=validateStructure;
validateStructure=function(s){for(const c of s.components){if(c.basis==='Per Unit'&&c.lookup!=='Flat'&&editorType==='template'){if(!c.rates?.length)throw Error('No lookup values are available for '+c.name);const dims=lookupDimensions(c);for(const [j,r] of c.rates.entries())for(const [k,d] of dims.entries()){if(numericType(d.type)){if((r.keys[k]?.max==null||r.keys[k]?.max===''||Number.isNaN(r.keys[k]?.max))&&lastBand(c,j,k))r.keys[k].max='+';if(r.keys[k]?.max==='+'&&!lastBand(c,j,k))throw Error('Only the last range can have an open maximum.')}else if(!categoryValues(c,d).includes(String(r.keys[k])))throw Error('Lookup categories must come from the Unit registry.')}}}riderValidate(s)};
const riderSync=syncTemplateDefinitions;
syncTemplateDefinitions=function(s){const old=new Map(state.templates.filter(t=>t.structure===s.id).map(t=>[t.id,clone(t.components)]));riderSync(s);for(const t of state.templates.filter(t=>t.structure===s.id))for(const c of t.components){const previous=old.get(t.id)?.find(x=>x.id===c.id);if(previous)for(const k of ['conditionText','conditionTextCustom'])c[k]=previous[k]}};
// A clearly identified demo rider lets users inspect examples without assigning them to existing riders.
if(!users.some(u=>u.id==='RDR-DEMO'))users.push({id:'RDR-DEMO',name:'Demo rider',lob:'Last Mile',entity:'Rider',type:'LMA',center:'DEMO',attendance_days:1,absent_days:0,total_km:36,closure:.96});
if(!state.riderPreviewVersion){for(const t of state.templates.filter(t=>t.structure.startsWith('sample-')))state.assignments.push({id:'demo-'+t.id,kind:'User',target:'RDR-DEMO',template:t.id});state.riderPreviewVersion=1;for(const t of state.templates)for(const c of t.components){c.valueFormat||=/\/\s*100/.test(c.formula)?'Percentage':'Amount';if(!c.conditionTextCustom)c.conditionText=conditionWords(c)}save()}

// The structure owns value presentation. Preserve existing choices once, then apply Admin settings.
for(const s of state.structures)for(const c of s.components){c.valueFormat||=state.templates.filter(t=>t.structure===s.id).map(t=>t.components.find(x=>x.id===c.id)?.valueFormat).find(Boolean)||'Amount';for(const t of state.templates.filter(t=>t.structure===s.id)){const tc=t.components.find(x=>x.id===c.id);if(tc)tc.valueFormat=c.valueFormat}}
save();
